// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, "", ""); }
    function testFuzz_property(address burner, uint256 burnAmount, address target, uint256 mintAmount) public {
        vm.assume(burner != address(0) && target != address(0));
        vm.assume(burnAmount > 0 && burnAmount <= type(uint256).max / 2);
        vm.assume(mintAmount > 0 && mintAmount <= type(uint256).max / 2);
        // Prepare: mint some tokens to burner and target
        vm.prank(c.owner());
        c.mintToken(burner, mintAmount);
        vm.prank(c.owner());
        c.mintToken(target, mintAmount);
        vm.prank(burner);
        uint256 balanceBeforeBurn = c.balanceOf(burner);
        bool success = false;
        try c.burn(burnAmount) {
            success = true;
        } catch {
            success = false;
        }
        uint256 balanceAfterBurn = c.balanceOf(burner);
        // The rule: the burner's balance should not increase after a burn
        assertTrue(balanceAfterBurn <= balanceBeforeBurn);
    }
}

